import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import '../../../../../Core/Storage/Remote/api_error_handler.dart';import '../../data/entities/login_model.dart';import '../../data/entities/register_model.dart';import '../../data/entities/user_data_model.dart';import '../../data/repositories/authentication.dart';import '../../data/sources/authentication_sources.dart';class AuthenticationRepoImpl extends AuthenticationRepo {  @override  Future<Either<Failure, UserDataModel>> loginByEmail(LoginModel loginModel) async {    try {      final response = await AuthenticationSources.getUserDataByEmail(loginModel);      if (response != null && response.status) {        return right(response.data!);      } else {        return left(ServerFailure(response?.message ?? "Login failed"));      }    } catch (e) {      if (e is DioException) {        if (e.response?.statusCode == 401) {          return left(ServerFailure.unauthorized());        }        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e.toString()));      }    }  }  @override  Future<Either<Failure, bool>> registerByEmail(      RegisterModel registerModel) async {    try {      final response = await createAccount(registerModel);      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }}